\define cycle-leadmark-mass()
<$vars
	todo1="[ ] "
	todo2="- [ ] "
	done1="[x] "
	done2="[X] "
	done3="- [x] "
	done4="- [X] "
	num1="<<num>> "
>
	<$let
		srcTodo={{{ [<source>tag[done]then<todo1>] ~[<done1>] }}}
		nextState={{{ [<source>get[text]prefix<num1>then[none]] ~[<source>get[text]prefix<done1>then<num1>] ~[<source>get[text]prefix<done2>then<num1>] ~[<source>get[text]prefix<done3>then<num1>] ~[<source>get[text]prefix<done4>then<num1>] ~[<source>get[text]prefix<todo1>then<srcTodo>] ~[<source>get[text]prefix<todo2>then<srcTodo>] ~[<todo1>] }}}
	>
		<$let
			t={{{ [<target>get[text]] }}}
			stripped={{{ [<t>removeprefix<todo1>] ~[<t>removeprefix<todo2>] ~[<t>removeprefix<done1>] ~[<t>removeprefix<done2>] ~[<t>removeprefix<done3>] ~[<t>removeprefix<done4>] ~[<t>removeprefix<num1>] ~[<t>] }}}
		>
			<$list filter="[<nextState>match[none]]" variable="_NULL">
				<$action-setfield $tiddler=<<target>> text=<<stripped>>/>
			</$list>
			<$list filter="[<nextState>!match[none]]" variable="_NULL">
				<$action-setfield $tiddler=<<target>> text={{{ [<stripped>addprefix<nextState>] }}}/>
			</$list>
			<$action-listops $tiddler=<<target>> $tags="-[[done]]"/>
		</$let>
	</$let>
</$vars>
\end

<$list filter="[<currentTiddler>get[stream-list]enlist-input[]is[tiddler]count[]!match[0]]" variable="_NULL">
	<$let source={{{ [<currentTiddler>get[stream-list]enlist-input[]is[tiddler]first[]] }}}>
		<$list filter="[enlist{!!stream-list}is[tiddler]]" variable="target">
			<<cycle-leadmark-mass>>
		</$list>
	</$let>
</$list>
<$list filter="[<currentTiddler>get[stream-list]enlist-input[]is[tiddler]count[]match[0]]" variable="_NULL">
	<$let source=<<currentTiddler>>>
		<$list filter="[<currentTiddler>get[parent]get[stream-list]enlist-input[]is[tiddler]count[]!match[0]]" variable="_NULL">
			<$set name="currentTiddler" filter="[<currentTiddler>get[parent]]" select="0">
				<$list filter="[enlist{!!stream-list}is[tiddler]]" variable="target">
					<<cycle-leadmark-mass>>
				</$list>
			</$set>
		</$list>
		<$list filter="[<currentTiddler>get[parent]get[stream-list]enlist-input[]is[tiddler]count[]match[0]]" variable="_NULL">
			<$list filter="[<currentTiddler>is[tiddler]]" variable="target">
				<<cycle-leadmark-mass>>
			</$list>
		</$list>
	</$let>
</$list>"},"$:/lithic/streams/contextmenu/highlight":{"title":"$:/lithic/streams/contextmenu/highlight","tags":"$:/tags/streams/contextmenu","sq-contextmenu-name":"highlight","type":"text/vnd.tiddlywiki","text":"<$action-listops $tiddler=<<currentTiddler>> $tags="+[toggle[Highlight]]"/>
"},"$:/lithic/streams/styles/ctx-preview":{"title":"$:/lithic/streams/styles/ctx-preview","tags":"$:/tags/Stylesheet","type":"text/vnd.tiddlywiki","text":"\rules except dash
\whitespace trim
\define ctx-preview-rules()
.stream-row[data-node-title="{{!!current}}"] .stream-node-handle .stream-node-handle-inner {
	border-color: <<colour primary>>;
}
\end
/* Highlight band for the context-menu preview target.

   Colors come from the contrast core (--lithic-c-notify-bg / -fg) so this band is
   byte-identical to the context-menu target band, and its ink is contrast-locked on
   palettes whose own notification/message pair is unreadable. Do not swap these for
   raw palette macros: those bypass the lock and drift from the menu band.

   The rule-set pragma above is load-bearing: the core dash rule rewrites a literal
   double hyphen into an en-dash, which silently kills every var() below, so the
   exclusion must stay. Keep this comment AFTER the define: pragmas are only
   recognised in the leading block, so any non-pragma content ends the pragma scan
   and leaves the define unparsed (which leaks its \end token into the CSS).

   Static fallbacks live in the lithic-core contrast stylesheet. */

<$vars currentTiddler={{{[prefix[$:/state/sq-context-popup]]}}}>
<<ctx-preview-rules>>
<$let
	ctxCurrent={{{ [<currentTiddler>get[current]!is[blank]first[]] }}}
>
<$list filter="[<ctxCurrent>!is[blank]]" variable="_NULL">
<$list filter="[<ctxCurrent>get[stream-list]enlist-input[]is[tiddler]count[]!match[0]]" variable="_NULL">
<$list filter="[<ctxCurrent>get[stream-list]enlist-input[]is[tiddler]]" variable="previewNode">
.stream-root:has(.sq-contextmenu .sq-ctx-item:hover) [data-node-title="<<previewNode>>"] {
	background: var(--lithic-c-notify-bg);
	color: var(--lithic-c-notify-fg);
}
.stream-root:has(.sq-contextmenu .sq-ctx-item:hover) [data-node-title="<<previewNode>>"] .stream-node-handle .stream-node-handle-inner {
	border: 5px solid <<colour primary>>;
	opacity: 1;
}
</$list>
</$list>
<$list filter="[<ctxCurrent>get[stream-list]enlist-input[]is[tiddler]count[]match[0]]" variable="_NULL">
<$list filter="[<ctxCurrent>get[parent]get[stream-list]enlist-input[]is[tiddler]]" variable="previewNode">
.stream-root:has(.sq-contextmenu .sq-ctx-item:hover) [data-node-title="<<previewNode>>"] {
	background: var(--lithic-c-notify-bg);
	color: var(--lithic-c-notify-fg);
}
.stream-root:has(.sq-contextmenu .sq-ctx-item:hover) [data-node-title="<<previewNode>>"] .stream-node-handle .stream-node-handle-inner {
	border: 5px solid <<colour primary>>;
	opacity: 1;
}
</$list>
</$list>
</$list>
</$let>
</$vars>
"},"$:/lithic/streams/styles/ctxmenu-vars":{"title":"$:/lithic/streams/styles/ctxmenu-vars","tags":"$:/tags/Stylesheet","type":"text/css","text":"/*
Streams context menu -- palette contrast override.

Upstream $:/plugins/sq/streams contextmenu-styles.css hardcodes a light theme
(#4b5155 text on #dce0e2 border). This sheet re-skins the same selectors from
the lithic contrast core (--lithic-c-menu-*): item text, icons, hover band and
borders are WCAG-checked against the live palette. Specificity is kept one
class above upstream so ordering does not matter.
*/

/* surface */
.tc-drop-down.sq-contextmenu {
	background-color: var(--lithic-c-menu-bg);
	border: 1px solid var(--lithic-c-menu-border);
	box-shadow: rgba(0, 0, 0, 0.35) 0px 2px 20px;
}

/* item text */
.tc-drop-down.sq-contextmenu .tc-menu-list-item {
	color: var(--lithic-c-menu-fg);
	background: transparent;
}

/* shortcut hints / icons */
.tc-drop-down.sq-contextmenu .sq-contextmenu-itemicon {
	color: var(--lithic-c-menu-muted);
}

/* hover / focused item. The ink needs !important: the base item ink is pinned
   !important by $:/lithic/streams-menu-fix, and an !important declaration cannot
   be outbid by specificity, so without this the hover band keeps the base ink. */
.tc-drop-down.sq-contextmenu .tc-menu-list-item:hover,
.tc-drop-down.sq-contextmenu .tc-menu-list-item:focus {
	background: var(--lithic-c-menu-hover-bg);
	color: var(--lithic-c-menu-hover-fg) !important;
}
.tc-drop-down.sq-contextmenu .tc-menu-list-item:hover .sq-contextmenu-itemicon,
.tc-drop-down.sq-contextmenu .tc-menu-list-item:focus .sq-contextmenu-itemicon {
	color: var(--lithic-c-menu-hover-fg) !important;
}

/* divider */
.tc-drop-down.sq-contextmenu .sq-contextmenu-divider {
	border-top-color: var(--lithic-c-menu-border);
}"},"$:/lithic/streams/styles/highlight":{"title":"$:/lithic/streams/styles/highlight","tags":"$:/tags/Stylesheet","text":".stream-row[data-node-tags~="Highlight"] > .sq-contextmenu-container .stream-node-handle-inner {
    background-color: <<colour primary>>;
    border-color: <<colour primary>>;
}

.stream-row[data-node-tags~="Highlight"] > .stream-node-block {
    border: 1px solid <<colour primary>>;
    border-radius: 4px;
    padding: 2px 6px;
    margin-left: -7px;
    margin-top: -3px;
    margin-bottom: -3px;
}
"},"$:/lithic/streams/styles/retain-fix.css":{"title":"$:/lithic/streams/styles/retain-fix.css","tags":"$:/tags/Stylesheet","type":"text/css","text":"@media screen {
    .stream-row-children[hidden] {
        display: none !important;
    }
}

.stream-node-handle-inner {
    border-radius: 1.5px !important;
}

/* For rich/tall stream rows, make the handle grow to fill the vertical space */
.stream-row-rich:not(.stream-row-editing) > .stream-node-control {
    bottom: 0 !important; /* Stretch control to full row height */
    align-items: flex-start !important; /* Push children to top if it's a flex container */
}

.stream-row-rich:not(.stream-row-editing) .stream-node-collapser {
    margin-top: 4px !important; /* Keep arrow aligned with text baseline */
}

.stream-row-rich:not(.stream-row-editing) .stream-node-handle {
    height: 100% !important;
    padding-top: 4px !important;
    padding-bottom: 25px !important;
    box-sizing: border-box !important;
}

.stream-row-rich:not(.stream-row-editing) .stream-node-handle-inner {
    height: 100% !important;
    width: 6px !important;
    min-height: 6px !important;
    border-radius: 1.5px !important;
}
"},"$:/plugins/sq/streams/action-macros":{"title":"$:/plugins/sq/streams/action-macros","tags":"$:/tags/Macro","text":"\define journal-date-pattern() ^[0-9]{1,2}(st|nd|rd|th) [A-Za-z]+ [0-9]{4}$

\define scaffold-missing-refs()
<$list filter="[{!!parent}links[]first[]]" variable="parentTag">
    <$list filter="[<currentTiddler>links[]is[missing]]" variable="missingLink">
        <$action-createtiddler $basetitle=<<missingLink>> type="text/x-markdown"/>
        <$action-listops $tiddler=<<missingLink>> $tags="[<parentTag>]"/>
    </$list>
</$list>
\end

\define swiped-right-actions()
<$list filter="[{$:/config/sq/streams/swipe-behaviour}match[contextmenu]]" variable="_NULL">
<$action-setfield $tiddler=<<contextmenu-state>> $field="current" $value=<<dom-data-node-title>>/>
<$action-setfield $tiddler=<<contextmenu-state>> $field="position" $value={{$:/config/sq/streams/swipe-contextmenu-position}}/>
<$action-popup $coords=<<tv-popup-abs-coords>> $state=<<contextmenu-state>>/>
</$list>
<$list filter="[{$:/config/sq/streams/swipe-behaviour}match[indent]]" variable="_NULL">
